/// Parse a timeout such as `30s`, `500ms`, `5m`, or `2h` into milliseconds.
pub fn parse_timeout(raw: &str) -> u64 {
    let value = raw.trim();
    // `"ms"` must be checked before the single-char suffixes: `"500ms"` also ends in `s`.
    let (digits, scale) = match value.strip_suffix("ms") {
        Some(ms) => (ms, 1),
        None => match value.strip_suffix('s') {
            Some(s) => (s, 1000),
            None => match value.strip_suffix('m') {
                Some(m) => (m, 60_000),
                None => match value.strip_suffix('h') {
                    Some(h) => (h, 3_600_000),
                    None => (value, 1),
                },
            },
        },
    };

